        // new HttpClientHandler() maps to the platform's native HTTP stack on Android and iOS.
        navigator.Reset(new SignInViewModel(navigator,
            (api, user) => ClientServices.Create(api, user, cacheRoot, new HttpClientHandler()))
        {
            ApiBase = apiBase,
        });
        return window;
    }
}

